# Estructura básica de una entidad gráfica
class Entidad2D:
    def __init__(self, x, y, ancho, alto, color):
        self.x = x
        self.y = y
        self.ancho = ancho
        self.alto = alto
        self.color = color
        self.vel_x = 2

    def actualizar(self):
        self.x += self.vel_x
        # Rebote en límites del canvas (560px ancho)
        if self.x + self.ancho >= 560 or self.x <= 0:
            self.vel_x *= -1

    def dibujar(self):
        campus.dibujar_rectangulo(self.x, self.y, self.ancho, self.alto, self.color)

def verificar_colision(box1, box2):
    return (
        box1['x'] < box2['x'] + box2['ancho'] and
        box1['x'] + box1['ancho'] > box2['x'] and
        box1['y'] < box2['y'] + box2['alto'] and
        box1['y'] + box1['alto'] > box2['y']
    )
